"use client";

import { useId, useState } from "react";

import { PlusIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { type PastRun, type Routine, RESULT_WORD, SAMPLE_NOW, SAMPLE_ROUTINES } from "./agent-routines/data";
import { RoutineRow } from "./agent-routines/routine-row";
import { useElapsed } from "./lib/timers";

/**
 * Scheduled agents in one card. Each routine reads as a sentence with its
 * schedule, a countdown to the next run, what it reads and where it posts.
 * A row opens to edit its schedule, and Run now starts a run by hand.
 */
export function AgentRoutines({ className }: { className?: string }) {
  const [routines, setRoutines] = useState<Routine[]>(SAMPLE_ROUTINES);
  const [openId, setOpenId] = useState<string | null>(null);
  const [freshId, setFreshId] = useState<string | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const titleId = useId();
  // The sample clock moves with real time, so countdowns tick down while the page is open.
  const now = SAMPLE_NOW + useElapsed(true) / 60;

  const onSchedule = routines.filter((routine) => routine.on).length;

  const update = (id: string, patch: Partial<Routine>) =>
    setRoutines((list) => list.map((routine) => (routine.id === id ? { ...routine, ...patch } : routine)));

  const recordRun = (routine: Routine, run: PastRun) => {
    setRoutines((list) => list.map((item) => (item.id === routine.id ? { ...item, history: [...item.history, run] } : item)));
    setAnnouncement(`${routine.name}: ${RESULT_WORD[run.result]}. ${run.note}.`);
  };

  const addRoutine = () => {
    const id = `new-${routines.length + 1}`;
    setRoutines((list) => [
      ...list,
      {
        id,
        name: "New routine",
        schedule: { kind: "weekdays", time: 9 * 60 },
        sources: ["diary"],
        destination: "chat",
        destinationLabel: "front desk channel",
        on: false,
        history: [],
        steps: ["Reading the diary", "Writing a summary"],
        doneNote: "Summary posted",
      },
    ]);
    setOpenId(id);
    setFreshId(id);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Routines
          </h2>
          <p className="text-sm text-muted-foreground">
            {onSchedule} of {routines.length} on schedule
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={addRoutine}>
          <PlusIcon aria-hidden="true" />
          New routine
        </Button>
      </header>

      <ul aria-label="Routines" className="flex flex-col">
        {routines.map((routine) => (
          <RoutineRow
            key={routine.id}
            routine={routine}
            now={now}
            open={openId === routine.id}
            fresh={freshId === routine.id}
            onOpenChange={(open) => {
              setOpenId(open ? routine.id : null);
              if (!open) setFreshId(null);
            }}
            onChange={(patch) => {
              update(routine.id, patch);
              if (patch.on !== undefined) setAnnouncement(`${routine.name} ${patch.on ? "is on schedule" : "is paused"}.`);
            }}
            onRunEnd={(run) => recordRun(routine, run)}
          />
        ))}
      </ul>
      <p aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

