import type { Status } from "../../lib/status";
import type { AppId } from "../parts/app-mark";

/** When a routine runs. Times are minutes after midnight. */
export type Schedule =
  | { kind: "hourly"; minute: number }
  | { kind: "daily"; time: number }
  | { kind: "weekdays"; time: number }
  | { kind: "weekly"; day: number; time: number };

/** How a run ended. */
export type RunResult = "ok" | "partial" | "failed" | "stopped";

/** One past run. `at` is minutes from the start of the sample week. */
export interface PastRun {
  at: number;
  result: RunResult;
  note: string;
}

/** One scheduled agent. */
export interface Routine {
  id: string;
  name: string;
  schedule: Schedule;
  /** The apps the agent reads from. */
  sources: AppId[];
  /** Where the agent posts what it found. */
  destination: AppId;
  destinationLabel: string;
  on: boolean;
  /** Past runs, oldest first. */
  history: PastRun[];
  /** The steps a run walks through, as present-tense phrases. */
  steps: string[];
  /** The note a finished run leaves. */
  doneNote: string;
}

/** The sample clock starts on Tuesday 10 November 2026 at 07:42, counted in minutes from Monday 00:00. */
export const SAMPLE_NOW = 1440 + 7 * 60 + 42;

const WEEK_START = Date.UTC(2026, 10, 9);
const MINUTES_IN_DAY = 1440;

/** The day names, Monday first, as a schedule counts them. */
export const DAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

/** Status colour for each run result. A stopped run has none and shows in muted ink. */
export const RESULT_STATUS = { ok: "good", partial: "watch", failed: "bad", stopped: null } satisfies Record<RunResult, Status | null>;

/** The word for each run result. */
export const RESULT_WORD = { ok: "Finished", partial: "Partly done", failed: "Failed", stopped: "Stopped" } satisfies Record<RunResult, string>;

const clock = (minutes: number) => `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;

/** A time of day such as "08:00", from minutes after midnight. */
export const formatClock = (minutes: number) => clock(((minutes % MINUTES_IN_DAY) + MINUTES_IN_DAY) % MINUTES_IN_DAY);

/** The schedule as a short phrase, such as "Weekdays at 08:00". */
export function describeSchedule(schedule: Schedule) {
  switch (schedule.kind) {
    case "hourly":
      return `Every hour at :${String(schedule.minute).padStart(2, "0")}`;
    case "daily":
      return `Every day at ${clock(schedule.time)}`;
    case "weekdays":
      return `Weekdays at ${clock(schedule.time)}`;
    case "weekly":
      return `${DAY_NAMES[schedule.day]}s at ${clock(schedule.time)}`;
  }
}

function matches(schedule: Schedule, minute: number) {
  const day = (((Math.floor(minute / MINUTES_IN_DAY) % 7) + 7) % 7);
  const time = ((minute % MINUTES_IN_DAY) + MINUTES_IN_DAY) % MINUTES_IN_DAY;
  switch (schedule.kind) {
    case "hourly":
      return time % 60 === schedule.minute;
    case "daily":
      return time === schedule.time;
    case "weekdays":
      return day < 5 && time === schedule.time;
    case "weekly":
      return day === schedule.day && time === schedule.time;
  }
}

/** The first minute after `now` that the schedule runs at. */
export function nextRun(schedule: Schedule, now: number) {
  const start = Math.floor(now) + 1;
  for (let minute = start; minute < start + 8 * MINUTES_IN_DAY; minute += 1) {
    if (matches(schedule, minute)) return minute;
  }
  return start;
}

/** The last `count` minutes at or before `now` that the schedule ran at, oldest first. */
export function pastRuns(schedule: Schedule, now: number, count: number) {
  const found: number[] = [];
  for (let minute = Math.floor(now); found.length < count && minute > now - 60 * MINUTES_IN_DAY; minute -= 1) {
    if (matches(schedule, minute)) found.push(minute);
  }
  return found.reverse();
}

/** How long until a run, such as "18 min", "2 h 14 min" or "3 d 9 h". */
export function formatCountdown(minutes: number) {
  const whole = Math.max(1, Math.ceil(minutes));
  if (whole < 60) return `${whole} min`;
  if (whole < MINUTES_IN_DAY) return `${Math.floor(whole / 60)} h ${whole % 60} min`;
  return `${Math.floor(whole / MINUTES_IN_DAY)} d ${Math.floor((whole % MINUTES_IN_DAY) / 60)} h`;
}

const DAY_LABEL = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" });

/** A run time as a date and clock, such as "Mon 9 Nov, 08:00". */
export const formatRunTime = (minute: number) => `${DAY_LABEL.format(new Date(WEEK_START + Math.floor(minute) * 60_000))}, ${formatClock(Math.floor(minute))}`;

/** Builds a history from a pattern, one letter per run: o finished, p partly, f failed. */
function history(schedule: Schedule, pattern: string, notes: Record<RunResult, string>, until = SAMPLE_NOW): PastRun[] {
  const results = [...pattern].map((letter): RunResult => (letter === "f" ? "failed" : letter === "p" ? "partial" : "ok"));
  return pastRuns(schedule, until, results.length).map((at, index) => {
    const result = results[index] ?? "ok";
    return { at, result, note: notes[result] };
  });
}

