const STEP_MS = 1300;

/** Props for one routine. */
export interface RoutineRowProps {
  routine: Routine;
  /** The sample clock, in minutes from the start of the sample week. */
  now: number;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onChange: (patch: Partial<Pick<Routine, "name" | "schedule" | "on">>) => void;
  onRunEnd: (run: PastRun) => void;
  /** True for a routine just added: its name field takes focus. */
  fresh: boolean;
}

/**
 * One routine as a row that reads like a sentence: its name, when it runs and
 * how long until the next run, what it reads and where it posts, an on and off
 * switch, the last run and a strip of past runs. Run now starts a simulated
 * run that steps through its work; the same button stops it.
 */
export function RoutineRow({ routine, now, open, onOpenChange, onChange, onRunEnd, fresh }: RoutineRowProps) {
  const [run, setRun] = useState<{ key: number; step: number } | null>(null);
  const [runCount, setRunCount] = useState(0);
  const editorId = useId();
  const nameId = useId();

  const finish = (result: RunResult, note: string) => {
    setRun(null);
    onRunEnd({ at: now, result, note });
  };

  useSchedule(
    run
      ? [
          ...routine.steps.slice(1).map((_, index) => ({ after: STEP_MS, run: () => setRun((current) => (current ? { ...current, step: index + 1 } : current)) })),
          { after: STEP_MS, run: () => finish("ok", routine.doneNote) },
        ]
      : null,
    run ? run.key : -1,
  );

  const start = () => {
    setRunCount((count) => count + 1);
    setRun({ key: runCount + 1, step: 0 });
  };
  const stop = () => finish("stopped", "Stopped by hand");

  const last = routine.history[routine.history.length - 1];
  const LastIcon = last ? RESULT_ICON[last.result] : null;
  const lastStatus = last ? RESULT_STATUS[last.result] : null;
  const lastTone = lastStatus ? STATUS_TEXT[lastStatus] : "text-muted-foreground";
  const next = nextRun(routine.schedule, now);

  const when = routine.on ? `${describeSchedule(routine.schedule)}, next run in ${formatCountdown(next - now)}` : `${describeSchedule(routine.schedule)}, paused`;

  return (
    <li className="relative border-b border-border last:border-b-0">
      <div className="grid gap-x-6 gap-y-3 px-5 py-4 @2xl:grid-cols-[1fr_auto] @2xl:items-center">
        <div className="flex min-w-0 flex-col gap-1.5">
          <div className="flex items-center gap-2">
            <Button
              id={nameId}
              variant="ghost"
              size="sm"
              aria-expanded={open}
              aria-controls={editorId}
              onClick={() => onOpenChange(!open)}
              className="-ml-2 h-auto min-h-9 min-w-0 justify-start"
            >
              <span className="truncate text-base">{routine.name || "Untitled routine"}</span>
              <ChevronDownIcon aria-hidden="true" className={cn("text-muted-foreground motion-safe:transition-transform", open && "rotate-180")} />
            </Button>
          </div>
          <p className="min-h-5 text-sm text-muted-foreground">
            {run ? (
              <span className="flex flex-wrap items-center gap-x-2">
                <ShimmerText text={routine.steps[run.step] ?? ""} active className="font-medium" />
                <span className="tabular-nums">
                  Step {run.step + 1} of {routine.steps.length}
                </span>
              </span>
            ) : (
              when
            )}
          </p>
          <p className="flex flex-wrap items-center gap-1.5 text-xs text-muted-foreground">
            <span className="sr-only">Reads from {routine.sources.map((app) => APP_NAME[app]).join(" and ")}, posts to</span>
            {routine.sources.map((app) => (
              <AppMark key={app} app={app} />
            ))}
            <span aria-hidden="true" className="px-0.5">
              to
            </span>
            <AppMark app={routine.destination} />
            <span>
              {APP_NAME[routine.destination]}, {routine.destinationLabel}
            </span>
          </p>
        </div>

        <div className="flex flex-col gap-2 @2xl:w-56 @2xl:items-end">
          <div className="flex items-center justify-between gap-3 @2xl:justify-end">
            <Button variant="outline" size="sm" onClick={run ? stop : start} aria-label={`${run ? "Stop" : "Run now"}: ${routine.name}`}>
              {run ? <StopIcon aria-hidden="true" /> : <PlayIcon aria-hidden="true" />}
              {run ? "Stop" : "Run now"}
            </Button>
            <Switch checked={routine.on} onCheckedChange={(on) => onChange({ on })} aria-label={`${routine.name} on schedule`} />
          </div>
          <p className="flex items-center gap-1.5 text-xs whitespace-nowrap text-muted-foreground">
            {LastIcon && last ? (
              <>
                <LastIcon aria-hidden="true" className={cn("size-3.5", lastTone)} />
                <span className="sr-only">{RESULT_WORD[last.result]}, </span>
                Last run {formatRunTime(last.at)}
              </>
            ) : (
              "Never run"
            )}
          </p>
          <RunTicks name={routine.name} runs={routine.history.slice(-14)} running={run !== null} />
        </div>
      </div>

      <Reveal open={open} id={editorId} className="px-5 pb-5">
        <div role="group" aria-labelledby={nameId} className="relative isolate rounded-xl border border-border p-4">
          <span aria-hidden="true" className="absolute inset-0 -z-10 rounded-xl bg-muted/40" />
          <ScheduleEditor
            name={routine.name}
            schedule={routine.schedule}
            preview={`Next run ${formatRunTime(next)}${routine.on ? "" : ", once the switch is on"}.`}
            onNameChange={(name) => onChange({ name })}
            onScheduleChange={(schedule: Schedule) => onChange({ schedule })}
            onDone={() => onOpenChange(false)}
            autoFocusName={fresh}
          />
        </div>
      </Reveal>
    </li>
  );
}

