/** The tick height for each result, so the strip reads without colour. */
const TICK_HEIGHT = { ok: "h-full", partial: "h-3/5", failed: "h-1/3", stopped: "h-1/4" } satisfies Record<RunResult, string>;

const tone = (result: RunResult) => {
  const status = RESULT_STATUS[result];
  return status ? STATUS_TEXT[status] : "text-muted-foreground";
};

/** Props for a strip of past runs. */
export interface RunTicksProps {
  name: string;
  runs: PastRun[];
  /** Adds a pulsing tick at the end for the run in progress. */
  running: boolean;
}

/**
 * One tick per past run, oldest first. It is one tab stop: arrows read each
 * run, Home and End jump, Escape clears. The inspected run keeps its colour
 * and gets a card with its time, result and note.
 */
export function RunTicks({ name, runs, running }: RunTicksProps) {
  const { index, plotProps } = usePointCursor(Math.max(1, runs.length), 4);
  const run = index === null ? null : runs[index];
  const frame = useRef<HTMLDivElement>(null);
  const strip = useRef<HTMLDivElement>(null);
  // The strip is only as wide as its ticks, so the card is placed against the wider column around it.
  const [tipX, setTipX] = useState(50);

  useLayoutEffect(() => {
    const tick = index === null ? null : strip.current?.children[index];
    const box = frame.current?.getBoundingClientRect();
    if (!tick || !box || box.width === 0) return;
    const rect = tick.getBoundingClientRect();
    setTipX(((rect.left + rect.width / 2 - box.left) / box.width) * 100);
  }, [index]);

  if (runs.length === 0) return <p className="text-xs text-muted-foreground">No runs yet</p>;

  return (
    <div ref={frame} className="relative w-full min-w-0">
      <div
        ref={strip}
        {...plotProps}
        role="application"
        aria-roledescription="run history"
        aria-label={`${name}, last ${runs.length} runs. Arrow keys read each run.`}
        className="relative flex h-6 w-fit touch-pan-y items-end gap-0.5 rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card @2xl:ml-auto"
      >
        {runs.map((item, position) => (
          <span
            key={`${item.at}-${position}`}
            aria-hidden="true"
            className={cn(
              "w-1.5 shrink-0 rounded-xs bg-current motion-safe:transition-opacity motion-safe:duration-150",
              tone(item.result),
              TICK_HEIGHT[item.result],
              index === null || index === position ? "opacity-100" : "opacity-30",
            )}
          />
        ))}
        {running ? (
          <span aria-hidden="true" className="h-full w-1.5 shrink-0 rounded-xs bg-chart-1 motion-safe:animate-pulse" />
        ) : null}
      </div>
      {run ? (
        <PointTip
          x={tipX}
          y={50}
          title={formatRunTime(run.at)}
          rows={[{ label: "Result", value: RESULT_WORD[run.result], marker: cn("bg-current", tone(run.result)) }]}
          note={run.note || undefined}
        />
      ) : null}
      <p aria-live="polite" className="sr-only">
        {run ? `${formatRunTime(run.at)}: ${RESULT_WORD[run.result]}${run.note ? `, ${run.note}` : ""}.` : ""}
      </p>
    </div>
  );
}

