import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { DAY_NAMES, type Schedule, formatClock } from "./data";

type Kind = Schedule["kind"];

const KINDS: { value: Kind; label: string }[] = [
  { value: "hourly", label: "Hourly" },
  { value: "daily", label: "Daily" },
  { value: "weekdays", label: "Weekdays" },
  { value: "weekly", label: "Weekly" },
];

const DAYS = DAY_NAMES.map((name, day) => ({ value: String(day), label: name.slice(0, 3) }));

/** The time of day a schedule runs at, or 9:00 for an hourly one. */
const timeOf = (schedule: Schedule) => (schedule.kind === "hourly" ? 9 * 60 + schedule.minute : schedule.time);

/** Moves a schedule to another kind and keeps its time of day. */
function withKind(schedule: Schedule, kind: Kind): Schedule {
  const time = timeOf(schedule);
  if (kind === "hourly") return { kind, minute: time % 60 };
  if (kind === "weekly") return { kind, day: schedule.kind === "weekly" ? schedule.day : 0, time };
  return { kind, time };
}

/** Props for the editor inside an open routine. */
export interface ScheduleEditorProps {
  name: string;
  schedule: Schedule;
  /** A sentence with the next run, read out when the schedule changes. */
  preview: string;
  onNameChange: (name: string) => void;
  onScheduleChange: (schedule: Schedule) => void;
  onDone: () => void;
  /** Focuses the name field on open, for a routine that was just added. */
  autoFocusName?: boolean;
}

/** Edits a routine's name and when it runs, with a live sentence that states the next run. */
export function ScheduleEditor({ name, schedule, preview, onNameChange, onScheduleChange, onDone, autoFocusName }: ScheduleEditorProps) {
  const nameId = useId();
  const timeId = useId();

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-col gap-1.5">
        <label htmlFor={nameId} className="text-sm font-medium">
          Name
        </label>
        <Input id={nameId} value={name} autoFocus={autoFocusName} onChange={(event) => onNameChange(event.target.value)} className="max-w-sm" />
      </div>
      <div className="flex flex-col gap-1.5">
        <span className="text-sm font-medium">Repeats</span>
        <div className="max-w-full overflow-x-auto scroll-fade-effect-x scrollbar-none">
          <SegmentedControl aria-label="Repeats" options={KINDS} value={schedule.kind} onValueChange={(kind) => onScheduleChange(withKind(schedule, kind))} />
        </div>
      </div>
      {schedule.kind === "weekly" ? (
        <div className="flex flex-col gap-1.5">
          <span className="text-sm font-medium">Day</span>
          <div className="max-w-full overflow-x-auto scroll-fade-effect-x scrollbar-none">
            <SegmentedControl
              aria-label="Day"
              options={DAYS}
              value={String(schedule.day)}
              onValueChange={(day) => onScheduleChange({ ...schedule, day: Number(day) })}
            />
          </div>
        </div>
      ) : null}
      <div className="flex flex-col gap-1.5">
        <label htmlFor={timeId} className="text-sm font-medium">
          {schedule.kind === "hourly" ? "Minutes past the hour" : "Time"}
        </label>
        {schedule.kind === "hourly" ? (
          <Input
            id={timeId}
            type="number"
            min={0}
            max={59}
            value={schedule.minute}
            onChange={(event) => {
              const minute = Math.min(59, Math.max(0, Math.round(Number(event.target.value) || 0)));
              onScheduleChange({ kind: "hourly", minute });
            }}
            className="w-24"
          />
        ) : (
          <Input
            id={timeId}
            type="time"
            value={formatClock(schedule.time)}
            onChange={(event) => {
              const [hours, minutes] = event.target.value.split(":").map(Number);
              if (hours === undefined || minutes === undefined || Number.isNaN(hours) || Number.isNaN(minutes)) return;
              onScheduleChange({ ...schedule, time: hours * 60 + minutes });
            }}
            className="w-32"
          />
        )}
      </div>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p aria-live="polite" className="text-sm text-muted-foreground">
          {preview}
        </p>
        <Button size="sm" onClick={onDone}>
          Done
        </Button>
      </div>
    </div>
  );
}
